/* Авторская практика ЕГЭ по геометрической и волновой оптике. */
(() => {
  const format = value => String(Number(value.toFixed(5))).replace('.', ',');
  function diagram(caption, coordinates, lines) {
    return {geometry: {
      caption,
      points: coordinates.map(([id, x, y, label]) => ({id, x, y, label: label || ''})),
      segments: lines.map(([from,to]) => ({from,to}))
    }};
  }

  const lens = diagram('Два главных луча. Предмет находится в 3F от линзы.', [
    ['L',30,150], ['R',610,150], ['O',330,150,'O'], ['U',330,35], ['D',330,275],
    ['A',60,90,'A'], ['B',330,90], ['C',465,180,'A′'],
    ['P',240,150,'F'], ['Q',420,150,'F']
  ], [['L','R'],['U','D'],['A','B'],['B','C'],['A','C']]);

  const variants = [
    ['Поворот зеркала', '°', n => [
      `Плоское зеркало повернули на ${n}° вокруг оси, перпендикулярной плоскости падения и проходящей через точку падения. Направление падающего луча сохранили. На сколько градусов повернулся отражённый луч? Луч остаётся с отражающей стороны зеркала.`, 2*n,
      'Нормаль поворачивается вместе с зеркалом. Угол отражения относительно новой нормали равен новому углу падения.',
      `Направление отражённого луча поворачивается на удвоенный угол поворота нормали: 2·${n} = ${2*n}°.`
    ]],
    ['Изображение в плоском зеркале', 'см', n => [
      `Точка A расположена на расстоянии ${4*n} см от плоского зеркала. Найди расстояние между точкой и её мнимым изображением в сантиметрах.`, 8*n,
      'У мнимого изображения и предмета одинаковые расстояния до зеркала.',
      `Отрезок между A и A′ перпендикулярен зеркалу. Его длина 2·${4*n} = ${8*n} см.`,
      diagram('Симметрия точки и изображения относительно зеркала', [['A',150,150,'A'],['B',490,150,'A′'],['U',320,40],['D',320,265]], [['A','B'],['U','D']])
    ]],
    ['Преломление на границе сред', '', n => {
      const index = 1.02 + 0.02*n, sinI = index/2;
      const x = 145*sinI, y = 145*Math.sqrt(1-sinI*sinI);
      return [
        `Луч переходит из воздуха в прозрачную среду. Синус угла падения равен ${format(sinI)}, угол преломления равен 30°. Найди показатель преломления среды. Для воздуха n₁ = 1.`, index,
        'Примени закон Снеллиуса n₁ sin i = n₂ sin r.',
        `n₂ = ${format(sinI)}/0,5 = ${format(index)}.`,
        diagram('Падение и преломление. Углы отсчитываются от нормали.', [['L',30,150,'граница'],['R',610,150],['N',320,10],['S',320,285],['O',320,150,'O'],['A',320-x,150-y,'падение'],['B',390,150+70*Math.sqrt(3),'преломление']], [['L','R'],['N','S'],['A','O'],['O','B']])
      ];
    }],
    ['Скорость света в среде', '10⁸ м/с', n => [
      `Показатель преломления прозрачной среды равен ${format(1+n/20)}. Найди скорость света в ней в единицах 10⁸ м/с. Прими c = 3·10⁸ м/с.`, 3/(1+n/20),
      'Абсолютный показатель преломления равен отношению c/v.',
      `v = 3·10⁸/${format(1+n/20)} м/с ≈ ${format(3/(1+n/20))}·10⁸ м/с.`
    ]],
    ['Полное внутреннее отражение', '', n => [
      `На границе прозрачного тела с воздухом предельный угол полного внутреннего отражения имеет синус ${format((40+n)/100)}. Каков показатель преломления тела? Для воздуха прими n₂ = 1.`, 100/(40+n),
      'Предельному углу соответствует преломлённый луч, идущий вдоль границы.',
      `n₁ sin θ = 1, откуда n₁ = 1/${format((40+n)/100)} ≈ ${format(100/(40+n))}.`
    ]],
    ['Изображение в собирающей линзе', 'см', n => [
      `Тонкая собирающая линза имеет фокусное расстояние ${2*n} см. Предмет стоит на главной оптической оси на расстоянии ${6*n} см. Найди расстояние от линзы до действительного изображения в сантиметрах.`, 3*n,
      'Используй 1/F = 1/d + 1/f для действительного изображения.',
      `f = Fd/(d − F) = ${2*n}·${6*n}/(${6*n} − ${2*n}) = ${3*n} см.`, lens
    ]],
    ['Линейное увеличение', 'мм', n => [
      `Предмет высотой ${2*n} мм находится на расстоянии 3F от тонкой собирающей линзы. Какова высота действительного изображения в миллиметрах?`, n,
      'Из формулы тонкой линзы при d = 3F следует f = 3F/2.',
      `Модуль увеличения f/d = 1/2. Высота изображения равна ${2*n}/2 = ${n} мм.`, lens
    ]],
    ['Оптическая сила двух линз', 'дптр', n => [
      `Две тонкие линзы вплотную соединены соосно. Оптическая сила собирающей линзы +${n+5} дптр, рассеивающей −5 дптр. Какова оптическая сила системы?`, n,
      'Оптические силы тонких линз в контакте складываются с учётом знаков.',
      `D = ${n+5} − 5 = ${n} дптр.`
    ]],
    ['Интерференция света', '', n => [
      `Два когерентных источника колеблются в фазе. Длина волны 520 нм, разность хода в точке наблюдения ${520*n} нм. Каков порядок интерференционного максимума в этой точке?`, n,
      'Максимум возникает при разности хода, кратной длине волны.',
      `Порядок максимума m = Δ/λ = ${520*n}/520 = ${n}.`
    ]],
    ['Дифракционная решётка', 'нм', n => [
      `На решётку с периодом ${(40+n)*4} мкм нормально падает монохроматический свет. Для максимума первого порядка sin θ = 0,0025. Найди длину волны в нанометрах.`, 10*(40+n),
      'Для максимума первого порядка d sin θ = λ.',
      `Умножаем период на 0,0025 и учитываем, что 1 мкм = 1000 нм. Получаем λ = ${(40+n)*4}·0,0025·1000 = ${10*(40+n)} нм.`
    ]]
  ];

  for (const [index, [title, unit, build]] of variants.entries()) {
    for (let variant = 1; variant <= 15; variant++) {
      const [question, rawAnswer, plan, calculation, figure] = build(variant + 1);
      const steps = [plan, calculation];
      tasks.push({
        id: `ege-physics-optics-${index + 1}-${variant}`,
        grade: 11,
        domain: 'physics',
        subject: 'physics',
        exam: 'ege',
        topic: 0,
        topicName: 'Оптика',
        examTopic: 'physics-ege-optics',
        level: index < 3 ? 0 : index < 7 ? 1 : 2,
        title, question, unit, steps,
        answer: Number(rawAnswer.toFixed(5)),
        hints: [plan],
        figure,
        solution: steps.join(' '),
        review: {plan},
        source: {
          name: 'Решу ЕГЭ',
          id: 'Оптика',
          type: 'тематический каталог',
          url: 'https://phys-ege.sdamgia.ru/test?theme=411',
          note: 'Авторская задача МатКлуба. По ссылке доступна дополнительная практика по теме.'
        }
      });
    }
  }
})();

